// Aggregate Jobs v9 — composite-key dedup (S2d) + tier-aware ordering
// Changes vs v8:
//   - Dedup by canonical apply-URL OR lowercased company+title, so the SAME job
//     surfaced by different sources (RemoteOK url vs Adzuna url vs web) collapses to one.
//   - On a collision, KEEP the lower source_tier (structured/ATS preferred over web),
//     and backfill salary + location onto the kept job from the dropped duplicate.
//   - (v8 carried over) tier-aware sort, Tier 3+ dropped, tier_counts for display.

// Recruiting aggregators that post on real ATSes (so they classify Tier 1) but are
// not the employer — demote to Tier 3 so the existing tier filter drops them.
const AGGREGATORS = new Set(['jobgether','weekdayworks','weekday','cutshort','instahyre','crossover','turing','braintrust','toptal','uplers','remotebase','hirist','talentprise']);
const sourceCounts = {};
const byKey = new Map(); // dedup key -> kept job (a job may be reachable by several keys)

function dedupKeys(job) {
  const ks = [];
  if (job.url) ks.push('u:' + job.url.replace(/[?#].*$/, '').replace(/\/+$/, '').toLowerCase());
  const ct = ((job.company || '') + '|' + (job.title || '')).toLowerCase().replace(/\s+/g, ' ').trim();
  if (ct.replace(/\|/g, '').length > 4) ks.push('ct:' + ct);
  return ks;
}

for (const item of $input.all()) {
  const jobs = item.json.jobs || [];
  const source = item.json.source || 'unknown';
  sourceCounts[source] = (sourceCounts[source] || 0) + jobs.length;
  for (const job of jobs) {
    if (!job || !job.url) continue;
    if (AGGREGATORS.has((job.company || '').toLowerCase())) { job.source_tier = 3; job.tier_label = 'aggregator'; }
    const ks = dedupKeys(job);
    let existing = null;
    for (const k of ks) { if (byKey.has(k)) { existing = byKey.get(k); break; } }
    if (!existing) { for (const k of ks) byKey.set(k, job); continue; }
    // collision: keep lower tier; backfill salary/location from the dropped dup
    const curTier = existing.source_tier || 99;
    const newTier = job.source_tier || 99;
    const keep = newTier < curTier ? job : existing;
    const drop = newTier < curTier ? existing : job;
    if (!keep.salary_min && drop.salary_min) { keep.salary_min = drop.salary_min; keep.salary_max = drop.salary_max; keep.salary_currency = drop.salary_currency; }
    if ((!keep.location || keep.location === 'unknown') && drop.location && drop.location !== 'unknown') keep.location = drop.location;
    for (const k of dedupKeys(existing)) byKey.set(k, keep);
    for (const k of ks) byKey.set(k, keep);
  }
}

const allJobs = Array.from(new Set(byKey.values()));

const expandCtx = $('Parse Expand Query').first().json;
const roleFamilies    = expandCtx.role_families    || [];
const excludedRoles   = expandCtx.excluded_roles   || [];
const locationCanon   = (expandCtx.location_canonical || '').trim().toLowerCase();
const remotePref      = expandCtx.remote_preference  || 'open';
const freshness       = expandCtx.freshness          || 'qdr:w';

const freshnessMs = { 'qdr:h': 3600000, 'qdr:d': 86400000, 'qdr:w': 604800000, 'qdr:m': 2592000000, 'qdr:y': 31536000000 }[freshness] || 604800000;
const cutoff = Date.now() - freshnessMs;

let filtered = allJobs;

// WS3: cohort-scoped search -- keep only jobs whose company fuzzy-matches the
// LLM-named target list (normalize case/punct; substring match both ways so
// "JPMorgan Chase & Co." matches target "JPMorgan").
const targetCompanies = expandCtx.target_companies || [];
if (targetCompanies.length) {
  const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const targets = targetCompanies.map(norm).filter(Boolean);
  filtered = filtered.filter((j) => {
    const c = norm(j.company);
    if (!c) return false;
    return targets.some((t) => c.includes(t) || t.includes(c));
  });
}

// Drop Tier 3 aggregators and Tier 4 unknown pages from the main ranked results.
filtered = filtered.filter(j => (j.source_tier || 4) < 3);

// Role family filter -- F2: word-boundary matching for every term length.
// Terms >3 chars used to fall back to plain haystack.includes(term), so
// "AI Engineering Intern" matched role family "AI Engineer" via the substring
// "engineer" inside "engineering". Word-boundary regex everywhere now, same
// as excluded_roles already correctly did.
function escapeRegexTerm(t) { return t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
if (roleFamilies.length > 0) {
  filtered = filtered.filter(j => {
    const haystack = (j.title + ' ' + (j.department || '')).toLowerCase();
    if (excludedRoles.some(excl => {
      const terms = excl.toLowerCase().split(/\s+/);
      return terms.every(t => new RegExp('\\b' + escapeRegexTerm(t) + '\\b').test(haystack));
    })) return false;
    return roleFamilies.some(variant => {
      const terms = variant.toLowerCase().split(/\s+/).filter(t => t.length > 1);
      return terms.every(term => new RegExp('\\b' + escapeRegexTerm(term) + '\\b').test(haystack));
    });
  });
}

// Location filter -- F2: 3-state policy (match/mismatch/unknown), applied
// uniformly to every source. No lane bypass -- the old firecrawl/serper/youcom
// skip let 62-98% of digest results through with zero location enforcement.
// Country-level fallback (city/country name recognition) covers broad queries
// where location_canonical is null but country is a real signal. Deliberately
// non-exhaustive -- anything unrecognized falls to 'unknown' (kept, demoted,
// badged), never a guessed drop.
const COUNTRY_NAMES = {
  US: ['usa','u.s.a','u.s.','united states','america'],
  IN: ['india'],
  GB: ['uk','u.k.','united kingdom','britain','england','scotland','wales'],
  CA: ['canada'],
  AU: ['australia'],
  DE: ['germany','deutschland'],
  SG: ['singapore'],
  AE: ['uae','united arab emirates','dubai','abu dhabi'],
  NL: ['netherlands','holland'],
  FR: ['france'],
  IE: ['ireland'],
  NZ: ['new zealand'],
};
const CITY_COUNTRY = {
  'new york':'US','san francisco':'US','seattle':'US','austin':'US','boston':'US',
  'chicago':'US','los angeles':'US','san jose':'US','denver':'US','atlanta':'US',
  'dallas':'US','houston':'US','washington':'US','miami':'US','portland':'US',
  'hyderabad':'IN','bangalore':'IN','bengaluru':'IN','mumbai':'IN','pune':'IN',
  'delhi':'IN','new delhi':'IN','gurgaon':'IN','gurugram':'IN','chennai':'IN',
  'noida':'IN','kolkata':'IN','ahmedabad':'IN',
  'london':'GB','manchester':'GB','edinburgh':'GB','birmingham':'GB',
  'toronto':'CA','vancouver':'CA','montreal':'CA','ottawa':'CA',
  'berlin':'DE','munich':'DE','frankfurt':'DE','hamburg':'DE',
  'singapore':'SG','dublin':'IE','amsterdam':'NL','paris':'FR','sydney':'AU','melbourne':'AU','auckland':'NZ',
};
function detectCountryFromLocation(hay) {
  for (const code of Object.keys(COUNTRY_NAMES)) { if (COUNTRY_NAMES[code].some(s => hay.includes(s))) return code; }
  for (const city of Object.keys(CITY_COUNTRY)) { if (hay.includes(city)) return CITY_COUNTRY[city]; }
  return null;
}
function checkLocationState(job, locTerms, countryCode) {
  const hay = (job.location || '').toLowerCase().trim();
  if (!hay || hay === 'unknown') return 'unknown';
  if (locTerms && locTerms.length) return locTerms.some(t => hay.includes(t)) ? 'match' : 'mismatch';
  if (countryCode) {
    const detected = detectCountryFromLocation(hay);
    if (!detected) return 'unknown';
    return detected === countryCode ? 'match' : 'mismatch';
  }
  return 'unknown';
}
const hasCityConstraint = locationCanon && !['any','anywhere','worldwide'].includes(locationCanon);
const locTerms = hasCityConstraint ? locationCanon.split(/[\s,]+/).filter(t => t.length > 1) : [];
// Country fallback only when there's no city-level signal AND the country isn't
// the silent "nothing stated" default (country always defaults to 'US' even on
// a totally generic query) -- avoids dropping results on unscoped searches.
const countryCode = (!locTerms.length && expandCtx.country && expandCtx.country !== 'US') ? expandCtx.country : null;
if (remotePref !== 'remote_only' && (locTerms.length || countryCode)) {
  filtered = filtered.filter(j => {
    const state = checkLocationState(j, locTerms, countryCode);
    j.location_verified = state === 'match' ? true : (state === 'unknown' ? null : false);
    return state !== 'mismatch';
  });
}

// Recency filter (soft)
filtered = filtered.filter(j => {
  if (!j.updated_at) return true;
  const t = new Date(j.updated_at).getTime();
  return isNaN(t) || t >= cutoff;
});

// Sort: verified-location first (only matters when location filtering was
// actually active -- location_verified is undefined on every job otherwise,
// making this a no-op), then tier, then recency within tier.
const _sortNewest = expandCtx.sort_by === 'newest';
filtered.sort((a, b) => {
  const locDiff = (a.location_verified === true ? 0 : 1) - (b.location_verified === true ? 0 : 1);
  if (locDiff !== 0) return locDiff;
  if (!_sortNewest) {
    const tierDiff = (a.source_tier || 99) - (b.source_tier || 99);
    if (tierDiff !== 0) return tierDiff;
  }
  const ad = new Date(a.updated_at || 0).getTime() || 0;
  const bd = new Date(b.updated_at || 0).getTime() || 0;
  return bd - ad;
});

// Tier composition for downstream display
const tierCounts = { 1: 0, 2: 0, '2.5': 0, 3: 0 };
for (const j of filtered) {
  const t = j.source_tier;
  if (t === 1) tierCounts[1]++;
  else if (t === 2) tierCounts[2]++;
  else if (t === 2.5) tierCounts['2.5']++;
  else if (t === 3) tierCounts[3]++;
}

const top = filtered.slice(0, 150);
return [{ json: {
  jobs: top, count: top.length, total_raw: allJobs.length,
  sources: sourceCounts, tier_counts: tierCounts,
  filter_applied: { role_families: roleFamilies, location: locationCanon || null, remote_preference: remotePref }
} }];

// Build Scorer Input v5 — resume_bubbles aware, compact by default.
const jobs = $('Experience Filter').first().json.jobs || [];
const sd = $getWorkflowStaticData('global');

function parseMaybe(v) {
  if (!v) return null;
  if (typeof v === 'string') { try { return JSON.parse(v); } catch(e) { return v; } }
  return v;
}
function firstPrimary(arr) {
  return Array.isArray(arr) ? (arr.find(x => x && x.primary) || arr[0] || {}) : {};
}
function clean(v) {
  const s = (v === null || v === undefined) ? '' : String(v).trim();
  if (!s || s.toLowerCase() === 'undefined' || s.toLowerCase() === 'null') return '';
  return s;
}
function locToString(loc) {
  if (!loc) return '';
  if (typeof loc === 'string') return clean(loc);
  return [loc.city, loc.region, loc.country].map(clean).filter(Boolean).join(', ');
}
function flatSkills(skills) {
  const out = [];
  if (skills && typeof skills === 'object') {
    for (const vals of Object.values(skills)) if (Array.isArray(vals)) out.push(...vals);
  }
  return [...new Set(out.map(s => String(s).trim()).filter(Boolean))];
}
function summarizeBubbles(r) {
  const parts = [];
  const p = r.personal || r.profile || {};
  const email = firstPrimary(p.emails).address || p.email || '';
  const loc = locToString(firstPrimary(p.locations)) || p.location || '';
  if (p.name) parts.push('CANDIDATE: ' + p.name);
  if (p.headline) parts.push('HEADLINE: ' + p.headline);
  if (email || loc) parts.push('CONTACT CONTEXT: ' + [email, loc].filter(Boolean).join(' | '));
  const wa = p.work_authorization;
  if (wa) parts.push('WORK AUTHORIZATION: ' + (typeof wa === 'object' ? Object.entries(wa).map(([k, v]) => k + ': ' + v).join(' | ') : String(wa)));
  const skillsList = flatSkills(r.skills);
  if (skillsList.length) parts.push('SKILLS: ' + skillsList.slice(0, 55).join(', '));
  const exp = Array.isArray(r.experience) ? r.experience : [];
  if (exp.length) {
    parts.push('EXPERIENCE EVIDENCE:\n' + exp.slice(0, 5).map(e => {
      const title = [e.title, e.company || e.organization].filter(Boolean).join(' @ ');
      const bullets = (e.bullets || []).slice(0, 4).map(b => '- ' + b).join('\n');
      return title + (bullets ? '\n' + bullets : '');
    }).join('\n\n'));
  }
  const projects = Array.isArray(r.projects) ? r.projects : [];
  if (projects.length) {
    parts.push('PROJECT EVIDENCE:\n' + projects.slice(0, 4).map(pj => {
      const title = pj.name || pj.title || 'Project';
      const bullets = (pj.bullets || []).slice(0, 3).map(b => '- ' + b).join('\n');
      return title + (bullets ? '\n' + bullets : '');
    }).join('\n\n'));
  }
  const edu = Array.isArray(r.education) ? r.education : [];
  if (edu.length) parts.push('EDUCATION: ' + edu.map(e => [e.degree, e.field, e.institution].filter(Boolean).join(' ')).join(' | '));
  return parts.join('\n\n').substring(0, 3500);
}
function summarizeStructured(r) {
  if (!r || typeof r !== 'object') return '';
  if (r.kind === 'resume_bubbles') {
    const compact = r.compact_views?.scoring_profile || r.compact_views?.search_profile || '';
    return (compact || summarizeBubbles(r)).substring(0, 3500);
  }
  const parts = [];
  const p = r.personal || {};
  const email = firstPrimary(p.emails).address || p.email || '';
  const loc = locToString(firstPrimary(p.locations)) || p.location || '';
  if (p.name) parts.push('CANDIDATE: ' + p.name);
  if (p.headline) parts.push('HEADLINE: ' + p.headline);
  if (email || loc) parts.push('CONTACT CONTEXT: ' + [email, loc].filter(Boolean).join(' | '));
  if (Array.isArray(r.summary_bullets) && r.summary_bullets.length) {
    parts.push('SUMMARY:\n' + r.summary_bullets.slice(0, 6).map(b => '- ' + b).join('\n'));
  }
  if (Array.isArray(r.experience) && r.experience.length) {
    const expBlocks = r.experience.slice(0, 5).map(e => {
      const dates = (e.start_date || '?') + ' to ' + (e.is_current ? 'current' : (e.end_date || '?'));
      const bullets = [];
      (e.projects || []).slice(0, 3).forEach(pr => {
        if (pr.name) bullets.push('Project: ' + pr.name + (Array.isArray(pr.tech) && pr.tech.length ? ' [' + pr.tech.slice(0, 8).join(', ') + ']' : ''));
        (pr.bullets || []).slice(0, 4).forEach(b => bullets.push(b));
      });
      (e.bullets || []).slice(0, 4).forEach(b => bullets.push(b));
      return (e.title || 'Role') + ' @ ' + (e.company || e.organization || 'Company') + ' (' + dates + ')' + (bullets.length ? '\n  ' + bullets.slice(0, 8).map(b => '- ' + b).join('\n  ') : '');
    });
    parts.push('EXPERIENCE:\n' + expBlocks.join('\n\n'));
  }
  if (Array.isArray(r.projects) && r.projects.length) {
    const projBlocks = r.projects.slice(0, 6).map(pj => {
      const tech = Array.isArray(pj.tech) && pj.tech.length ? ' [' + pj.tech.slice(0, 8).join(', ') + ']' : '';
      const bullets = (pj.bullets || []).slice(0, 3).map(b => '- ' + b).join('\n  ');
      return (pj.name || pj.title || 'Project') + tech + (bullets ? '\n  ' + bullets : '');
    });
    parts.push('PROJECTS:\n' + projBlocks.join('\n'));
  }
  const skillsList = flatSkills(r.skills);
  if (skillsList.length) parts.push('SKILLS: ' + skillsList.slice(0, 60).join(', '));
  if (Array.isArray(r.education) && r.education.length) {
    parts.push('EDUCATION: ' + r.education.map(e => [e.degree, e.field, e.institution].filter(Boolean).join(' ') + (e.gpa ? ' GPA ' + e.gpa : '')).join(' | '));
  }
  return parts.join('\n\n').substring(0, 6000);
}

const rows = $input.all().map(i => i.json || {});
let row = rows.find(r => r && (r.id === 'global:resume_structured' || r.value)) || rows[0] || {};
let resume = parseMaybe(row.value || null);
if (resume && resume.resume_doc) resume = resume.resume_doc;
if ((!resume || typeof resume !== 'object' || !resume.personal) && sd.last_resume_structured) resume = sd.last_resume_structured;
if ((!resume || typeof resume !== 'object') && sd.last_resume_json) resume = sd.last_resume_json;

let resumeSummary = summarizeStructured(resume);
let resumeMissing = !resumeSummary;
if (resumeMissing) resumeSummary = 'No resume found - please run resume setup first';

// Phase 4.1: cap the batch sent to the LLM scorer -- Aggregate Jobs now surfaces up
// to 150 candidates (widened cache-first pool), but deep-scoring all of them would
// multiply JobScorer's cost/latency for no benefit; the rest are still shown in the
// Telegraph appendix (Build Telegraph Body), ranked by cache relevance instead.
const jobBatch = jobs.slice(0, 30).map(j => ({
  job_id: j.job_id, title: j.title, company: j.company, location: j.location,
  department: j.department, url: j.url, description_snippet: j.description_snippet,
  source: j.source, source_tier: j.source_tier, source_tier_label: j.source_tier_label || j.tier_label,
  required_yoe_min: j.required_yoe_min ?? null, required_yoe_max: j.required_yoe_max ?? null,
  yoe_compat_score: j.yoe_compat_score ?? null,
  salary_min: j.salary_min ?? null, salary_max: j.salary_max ?? null, salary_currency: j.salary_currency || null
}));

let _eq = {}; try { _eq = $('Parse Expand Query').first().json || {}; } catch(_) {}
return [{ json: {
  master_resume_summary: resumeSummary,
  resume_missing: resumeMissing,
  resume_kind: resume && typeof resume === 'object' ? (resume.kind || 'structured') : 'none',
  resume_source: resumeMissing ? 'none' : (row.id ? 'file' : 'staticData'),
  requested_location: _eq.location_canonical || null,
  requested_remote: _eq.remote_preference || null,
  requested_country: _eq.country || null,
  jobs: jobBatch
} }];

const staticData = $getWorkflowStaticData('global');
let chatId, rawMessage, entities;
try {
  chatId = $('Extract Input').first().json.chat_id;
  rawMessage = $('Telegram Trigger').first().json.message?.text || '';
  entities = $('Route Intent').first().json.output?.entities || {};
} catch (e) {
  const cb = $('Extract Callback').first().json;
  // s53: double-tap lock -- a second jd:generate tap while a run is already
  // in flight would launch a full duplicate apply pipeline racing the first
  // on staticData. Timestamp TTL (180s) so a crashed run can't stick the lock.
  const _inflight = staticData.jd_generate_inflight;
  if (_inflight && (Date.now() - _inflight) < 180000) {
    return [{ json: { chat_id: cb.chat_id, error: 'Already generating from this JD — hang tight, your resume + cover letter are on the way.' } }];
  }
  const pending = staticData.last_pasted_jd;
  if (!pending || !pending.jd_text) {
    return [{ json: { chat_id: cb.chat_id, error: 'That pasted job description expired or was not found. Please paste it again.' } }];
  }
  const cbId = ((cb.callback_data || '').split(':')[2]) || null;
  if (pending.id && cbId !== pending.id) {
    return [{ json: { chat_id: cb.chat_id, error: 'That menu belongs to an older pasted job description (a newer one replaced it). Please use the newest menu or paste the JD again.' } }];
  }
  const ttlSec = pending.ttl_seconds || 1800;
  const ageSec = (Date.now() - new Date(pending.created_at).getTime()) / 1000;
  if (ageSec > ttlSec) {
    return [{ json: { chat_id: cb.chat_id, error: 'That pasted job description expired. Please paste it again.' } }];
  }
  staticData.jd_generate_inflight = Date.now();
  const company = pending.company || 'unknown';
  const companySlug = company.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'unknown';
  return [{ json: { chat_id: cb.chat_id, job_number: 0, source: 'jd_paste', company_slug: companySlug, greenhouse_id: null, job: { job_id: `jdpaste-${companySlug}-${Date.now()}`, title: pending.role || '', company, location: '', url: '', description_snippet: pending.jd_text } } }];
}
const jobNumber = entities.job_number;
const urlMatch = rawMessage.match(/https?:\/\/[^\s]+/);
if (urlMatch) {
  const jobUrl = decodeURIComponent(urlMatch[0]);
  let company = 'unknown'; let source = 'web';
  const m = { ashby: jobUrl.match(/jobs\.ashbyhq\.com\/([^\/]+)\//), lever: jobUrl.match(/jobs\.lever\.co\/([^\/]+)\//), greenhouse: jobUrl.match(/(?:boards|job-boards)\.greenhouse\.io\/([^\/]+)\//), workday: jobUrl.match(/([^.\/]+)\.wd\d+\.myworkdayjobs\.com\//), workable: jobUrl.match(/apply\.workable\.com\/([^\/]+)\//) };
  for (const [src, match] of Object.entries(m)) { if (match) { company = match[1]; source = src; break; } }
  // s54: hash the full URL into the id -- a constant `direct-<company>-0`
  // collided two different roles at one company in track's dedup.
  let _h = 5381; for (let _i = 0; _i < jobUrl.length; _i++) { _h = ((_h * 33) ^ jobUrl.charCodeAt(_i)) >>> 0; }
  return [{ json: { chat_id: chatId, job_number: 0, direct_url: jobUrl, source, company_slug: company, greenhouse_id: null, job: { job_id: `direct-${company}-${_h.toString(36)}`, title: '', company, location: '', url: jobUrl, description_snippet: '' } } }];
}
if (!jobNumber) return [{ json: { chat_id: chatId, error: 'No job number provided. Reply with a number (1-5) after a job search, or paste a job URL directly.' } }];
const lastJobs = staticData.last_jobs || {};
const job = lastJobs[jobNumber];
if (!job) return [{ json: { chat_id: chatId, error: `Job #${jobNumber} not found. Run a job search first, or paste a job URL directly.` } }];
// s52: reject a stale list -- a scheduled digest can silently replace the
// numbering hours after the user last saw it (same staleness class already
// guarded for last_pasted_jd, just no per-item id to key off here).
const listAgeSec = staticData.last_jobs_created_at ? (Date.now() - new Date(staticData.last_jobs_created_at).getTime()) / 1000 : 0;
if (listAgeSec > 14400) return [{ json: { chat_id: chatId, error: `That job list has expired (a newer search or scheduled digest replaced it). Please run a job search again and reply with a fresh number.` } }];
const parts = job.job_id.split('-');
const greenhouseId = parts.pop();
const companySlug = parts.join('-');
return [{ json: { chat_id: chatId, job_number: jobNumber, company_slug: companySlug, greenhouse_id: greenhouseId, source: job.source || 'greenhouse', job } }];

const retrieveData = $('Retrieve Job').first().json;
const scrapeResult = $input.first().json;
let jobDescription = retrieveData.job?.description_snippet || '';
if (scrapeResult) {
  const md = scrapeResult.markdown || (scrapeResult.data && scrapeResult.data.markdown) || '';
  if (md && md.length > 100) jobDescription = md.substring(0, 8000);
}
const metadata = scrapeResult?.metadata || scrapeResult?.data?.metadata || {};
const job = retrieveData.job || {};
const jobTitle = job.title || metadata.title?.replace(/ \| .*$/, '').trim() || 'Unknown Role';
const company = job.company || retrieveData.company_slug || metadata.ogSiteName || 'unknown';
return [{ json: { chat_id: retrieveData.chat_id, job_number: retrieveData.job_number, job_id: (job.job_id || ('slot-' + retrieveData.job_number)), job_title: jobTitle, company, company_slug: retrieveData.company_slug, location: job.location || metadata.geo_region || 'Unknown', job_url: retrieveData.direct_url || job.url || '', job_description: jobDescription, fit_score_from_digest: job.fit_score || null } }];

// Parse Personal Info v5 — local resume_structured.json (resume_bubbles/structured) first, legacy file fallback second.
const jobCtx = $('Prepare Job Context').first().json;

function parseMaybe(v) {
  if (!v) return null;
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch(e) { return v; }
  }
