  s = s.replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/…/g, '...')
       .replace(/[–—]/g, '--').replace(/ /g, ' ')
       .replace(/[→➔➡]/g, '->').replace(/•/g, '-')
       .replace(/₹/g, 'INR ').replace(/€/g, 'EUR ').replace(/£/g, 'GBP ');
