  const bal = (s) => { let d = 0; for (let k = 0; k < s.length; k++) { if (s[k] === '(') d++; else if (s[k] === ')') d--; } return d === 0; };
  const floor = Math.floor(MAX * 0.55);
  for (let i = cut.length - 1; i > floor; i--) {
