  let m;
  if ((m = t.match(/(\d+)\s*[-–to]+\s*(\d+)\s*(?:years?|yrs?)/i)))
    return { min: parseInt(m[1]), max: parseInt(m[2]) };
  if ((m = t.match(/(\d+)\+\s*(?:years?|yrs?)\s*(?:of\s*)?(?:experience|exp)/i)))
    return { min: parseInt(m[1]), max: 99 };
  if ((m = t.match(/(?:minimum|min\.?|at least)\s*(\d+)\s*(?:years?|yrs?)/i)))
    return { min: parseInt(m[1]), max: 99 };
  if ((m = t.match(/(\d+)\s*(?:years?|yrs?)\s*(?:of\s*)?(?:experience|exp)/i))) {
    const n = parseInt(m[1]);
    return { min: Math.max(0, n - 1), max: n + 2 };
  }
  for (const [label, range] of Object.entries(seniorityYoe)) {
    if (t.includes(label)) return { min: range.min, max: range.max };
  }
  return { min: null, max: null };
}

function calcCompatScore(jobMin, jobMax, userMaxYoe, seniorityPref) {
  if (jobMin === null && jobMax === null) return 1.0;
  if (!userMaxYoe && seniorityPref === 'any') return 1.0;
  let userMin = 0, userMax = userMaxYoe || 99;
  if (seniorityPref === 'junior') { userMin = 0; userMax = Math.min(userMax, 2); }
  else if (seniorityPref === 'mid') { userMin = 2; userMax = Math.min(userMax || 7, 7); }
  else if (seniorityPref === 'senior') { userMin = 5; userMax = 99; }
  const jMin = jobMin ?? 0, jMax = jobMax ?? 99;
  if (userMax >= jMin && userMin <= jMax) return 1.0;
  if (userMin > jMax) return Math.max(0.2, 1.0 - (userMin - jMax) * 0.15);
  if (userMax < jMin) return Math.max(0.1, 1.0 - (jMin - userMax) * 0.2);
  return 1.0;
}

const enrichedJobs = jobs.map(job => {
  const { min, max } = extractYoe(job.description_snippet || job.title || '');
  const compatScore = calcCompatScore(min, max, maxYoe, seniorityPref);
  return { ...job, required_yoe_min: min, required_yoe_max: max, yoe_compat_score: compatScore };
});

const filtered = (maxYoe || seniorityPref !== 'any')
  ? enrichedJobs.filter(j => j.yoe_compat_score >= 0.15)
  : enrichedJobs;

return [{ json: { jobs: filtered, count: filtered.length, filtered_out: enrichedJobs.length - filtered.length } }];

