const remoteAggregators = [
  'weworkremotely.com', 'remoteok.com', 'himalayas.app',
  'remotive.com', 'jobicy.com', 'wellfound.com', 'arbeitnow.com'
];
const includeDomains = remoteOnly ? [...standardATS, ...remoteAggregators] : standardATS;
const country = ctx.country || 'US';
const location = ctx.location_canonical || null;
const freshness = ctx.freshness || 'qdr:w';
const limit = remoteOnly ? 25 : 10;

const all = [...llmQueries, ...deterministic, ...remoteExtra];
const seen = new Set();
const queries = [];
for (const q of all) {
  if (!q) continue;
  const k = String(q).toLowerCase().trim();
  if (k && !seen.has(k)) { seen.add(k); queries.push(q); }
}

return queries.slice(0, 4).map(query => ({
  json: {
    _disabled: false,
    query,
    bodyObj: { query, limit, includeDomains, tbs: freshness, ignoreInvalidURLs: true, country, ...(location ? { location } : {}) }
  }
}));

// --- URL Tier Classifier ---------------------------------------------------
// Tiers: 1 = direct ATS, 2 = curated boards, 2.5 = unknown career page,
//        3 = general aggregator, 4 = unknown / probably not a job
function classifyUrlTier(url) {
  if (!url) return { tier: 4, label: 'invalid' };
  const u = url.toLowerCase();
  // TIER 1 — Direct ATS platforms
  if (/(?:boards|job-boards)\.greenhouse\.io/.test(u)) return { tier: 1, label: 'ats:greenhouse' };
  if (/jobs\.lever\.co/.test(u)) return { tier: 1, label: 'ats:lever' };
  if (/jobs\.ashbyhq\.com/.test(u)) return { tier: 1, label: 'ats:ashby' };
  if (/[\w-]+\.wd\d+\.myworkdayjobs\.com/.test(u)) return { tier: 1, label: 'ats:workday' };
  if (/apply\.workable\.com/.test(u)) return { tier: 1, label: 'ats:workable' };
  if (/jobs\.smartrecruiters\.com/.test(u)) return { tier: 1, label: 'ats:smartrecruiters' };
  if (/workatastartup\.com\/jobs\//.test(u)) return { tier: 1, label: 'ats:yc' };
  if (/[\w-]+\.recruitee\.com/.test(u)) return { tier: 1, label: 'ats:recruitee' };
  if (/[\w-]+\.personio\.(com|de)/.test(u)) return { tier: 1, label: 'ats:personio' };
  if (/[\w-]+\.bamboohr\.com/.test(u)) return { tier: 1, label: 'ats:bamboohr' };
  if (/[\w-]+\.jobvite\.com/.test(u)) return { tier: 1, label: 'ats:jobvite' };
  if (/careers-[\w-]+\.icims\.com/.test(u)) return { tier: 1, label: 'ats:icims' };
  if (/[\w-]+\.taleo\.net/.test(u)) return { tier: 1, label: 'ats:taleo' };
  if (/successfactors\.(com|eu)/.test(u)) return { tier: 1, label: 'ats:successfactors' };
  if (/[\w-]+\.eightfold\.ai/.test(u)) return { tier: 1, label: 'ats:eightfold' };
  // TIER 2 — Curated remote/aggregator boards
  if (/weworkremotely\.com\/(remote-jobs|listings)\//.test(u)) return { tier: 2, label: 'curated:wwr' };
  if (/remoteok\.(com|io)/.test(u)) return { tier: 2, label: 'curated:remoteok' };
  if (/himalayas\.app\/jobs\//.test(u)) return { tier: 2, label: 'curated:himalayas' };
  if (/remotive\.(com|io)\/(jobs|remote-jobs)\//.test(u)) return { tier: 2, label: 'curated:remotive' };
  if (/jobicy\.com/.test(u)) return { tier: 2, label: 'curated:jobicy' };
  if (/wellfound\.com\/jobs\//.test(u)) return { tier: 2, label: 'curated:wellfound' };
  if (/arbeitnow\.com\/jobs\//.test(u)) return { tier: 2, label: 'curated:arbeitnow' };
  if (/ai-jobs\.net\/job\//.test(u)) return { tier: 2, label: 'curated:aijobs' };
  if (/builtin(nyc|sf|la|chicago|seattle|boston|austin)?\.com\/job\//.test(u)) return { tier: 2, label: 'curated:builtin' };
  // TIER 3 — General web aggregators (often listings pages, low signal)
  if (/linkedin\.com/.test(u)) return { tier: 3, label: 'aggregator:linkedin' };
  if (/indeed\.com/.test(u)) return { tier: 3, label: 'aggregator:indeed' };
  if (/glassdoor\.com/.test(u)) return { tier: 3, label: 'aggregator:glassdoor' };
  if (/ziprecruiter\.com/.test(u)) return { tier: 3, label: 'aggregator:ziprecruiter' };
  if (/dice\.com/.test(u)) return { tier: 3, label: 'aggregator:dice' };
  if (/monster\.com/.test(u)) return { tier: 3, label: 'aggregator:monster' };
  if (/simplyhired\.com/.test(u)) return { tier: 3, label: 'aggregator:simplyhired' };
  if (/careerbuilder\.com/.test(u)) return { tier: 3, label: 'aggregator:careerbuilder' };
  if (/snagajob\.com/.test(u)) return { tier: 3, label: 'aggregator:snagajob' };
  if (/theladders\.com/.test(u)) return { tier: 3, label: 'aggregator:theladders' };
  if (/jora\.com/.test(u)) return { tier: 3, label: 'aggregator:jora' };
  if (/talent\.com/.test(u)) return { tier: 3, label: 'aggregator:talent' };
  if (/jobs2careers\.com/.test(u)) return { tier: 3, label: 'aggregator:jobs2careers' };
  // TIER 2.5 — Plausible career page on unrecognized domain
  if (/^https?:\/\/(careers|jobs|apply|hiring|talent|work|join)\.[\w-]+\.[\w.]+/.test(u)) {
    return { tier: 2.5, label: 'career:subdomain' };
  }
  if (/\/(careers|jobs|join-us|join_us|apply|positions|openings|opportunities|vacancies|hiring|work-with-us)\//.test(u)) {
    return { tier: 2.5, label: 'career:path' };
  }
  // TIER 4 — Anything else
  return { tier: 4, label: 'unknown' };
}

// Normalize Firecrawl Search results → standard job object
// Native node shape: { success, data: { web: [...], news: [...], images: [...] } }

const hits = $input.all();
const allJobs = [];

function extractCompanyFromUrl(url) {
  let m;
  if ((m = url.match(/(?:boards|job-boards)\.greenhouse\.io\/(?:embed\/job_board\?for=)?([^/?&#]+)/))) return m[1];
  if ((m = url.match(/jobs\.lever\.co\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.ashbyhq\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/([^.\/]+)\.wd\d+\.myworkdayjobs\.com/))) return m[1];
  if ((m = url.match(/apply\.workable\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.smartrecruiters\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/workatastartup\.com\/jobs\/\d+\/[^?#]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/jobs\/[^/]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/company\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)\./))) return url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)/)[0];
  if ((m = url.match(/^https?:\/\/(?:www\.)?([^.]+)\./))) return m[1];
  return 'unknown';
}

const DEGREE_ABBR = new Set(['BS','MS','MA','BA','JD','MD','MBA','PHD','BFA','MFA','LLM','BSC','MSC','BTECH','MTECH','BE','ME','RN','CPA']);
function extractLocationFromTitle(title) {
  // Pull common location patterns out of titles like "ML Engineer - New York, NY"
  let m;
  if ((m = title.match(/(?:in|at|–|-|·|—)\s*([A-Z][\w\s]+,\s*[A-Z]{2,})/))) {
    const candidate = m[1].trim();
    if (DEGREE_ABBR.has(candidate.split(',')[0].trim().toUpperCase())) return '';
    return candidate;
  }
  if ((m = title.match(/(?:in|at|–|-|·|—)\s*(New York|San Francisco|Seattle|Boston|Austin|Chicago|Los Angeles|Remote)/i))) return m[1];
  return '';
}

for (const item of hits) {
  if (item.json._disabled) continue;

  const data = item.json.data;
  let results = [];
  if (Array.isArray(data)) results = data;
  else if (data && Array.isArray(data.web)) results = data.web;
  else if (Array.isArray(item.json.results)) results = item.json.results;
  else if (Array.isArray(item.json.web)) results = item.json.web;

  for (const r of results) {
    const url = r.url || r.metadata?.sourceURL || '';
    if (!url) continue;
    const title = r.title || r.metadata?.title || '';
    const company = extractCompanyFromUrl(url);
    const location = r.metadata?.location || r.location || extractLocationFromTitle(title) || '';

    const __tier = classifyUrlTier(url);
    allJobs.push({
      job_id: 'fc-' + company + '-' + allJobs.length,
      title,
      company,
      location,
      department: '',
      url,
      description_snippet: (r.description || r.markdown || r.metadata?.description || '').substring(0, 600),
      updated_at: r.metadata?.publishedTime || r.publishedTime || '',
      source: 'firecrawl',
      source_tier: __tier.tier,
      tier_label: __tier.label
    });
  }
}

return [{ json: { jobs: allJobs, source: 'firecrawl', count: allJobs.length } }];

// Pre-flight: Providers v2
// All three providers now use n8n credentials (no env vars needed on Cloud).
// We assume each is active if the user has configured the credential — n8n
// will surface a per-node auth error if a credential is missing or invalid.
const ctx = $input.first().json;
const active = ['Firecrawl 🔥', 'You.com 🔍', 'Serper ⚡'];
// v9 A1: coarse location/remote pre-filter terms for Hybrid Cache Search's SQL --
// mirrors Aggregate Jobs' own hasCityConstraint/locTerms gate exactly so the SQL
// pre-filter and the real downstream JS filter never disagree on "is this even a
// location-scoped search." Deliberately duplicated, not shared (n8n Code nodes
// can't share modules) -- keep in sync with Aggregate Jobs if that gate changes.
const locationCanon = (ctx.location_canonical || '').trim().toLowerCase();
const hasCityConstraint = locationCanon && !['any', 'anywhere', 'worldwide'].includes(locationCanon);
const cacheLocTerms = hasCityConstraint ? locationCanon.split(/[\s,]+/).filter((t) => t.length > 1).join(',') : '';
const cacheRemoteOnly = ctx.remote_preference === 'remote_only' ? 'true' : '';
return [{ json: {
  ...ctx,
  _providers_active: active,
  _providers_count: active.length,
  _no_providers: false,
  cache_loc_terms: cacheLocTerms,
  cache_remote_only: cacheRemoteOnly
}}];

// Render user prefs as a human-readable Telegram message.
const sd = $getWorkflowStaticData("global");
const prefs = sd.user_prefs || {};
const skip = ["_schema_version", "_history", "_updated_at"];
const entries = Object.entries(prefs).filter(([k]) => !skip.includes(k));

if (!entries.length) {
  return [{ json: { message: "ℹ️ No preferences set yet. I'll remember things as you tell me.\n\nTry: \"remember I'm in NYC\" or \"set min salary to $150k\" or \"send me jobs at 9am and 5pm\"" } }];
}

// Pretty-render schedule_times if present
const renderSchedule = (times, tz) => {
  if (!Array.isArray(times)) return null;
  if (times.length === 0) return "_scheduled searches disabled_";
  const tzShort = (tz || "America/New_York").split("/").pop().replace(/_/g, " ");
  return `Daily at ${times.join(", ")} (${tzShort})`;
};

const lines = [];
const tz = prefs.timezone;
for (const [k, v] of entries) {
  if (k === "timezone") continue;                         // shown alongside schedule
  if (k === "schedule_times") {
    const rendered = renderSchedule(v, tz);
    lines.push(`• *schedule:* ${rendered}`);
    continue;
  }
  lines.push(`• *${k}:* ${JSON.stringify(v)}`);
}

const updatedAt = prefs._updated_at
  ? `\n\n_Last updated: ${new Date(prefs._updated_at).toLocaleDateString()}_`
  : "";

return [{ json: { message: `📋 *Your preferences:*\n\n${lines.join("\n")}${updatedAt}` } }];

// Handle Prefs Update v3
// Regex-based preference extractor. Schedule times rounded to 3-hour boundary
// to match the every-3-hours Schedule Tick cron.

const msg = ($('Extract Input').first().json.message_text || '').toLowerCase();
const sd  = $getWorkflowStaticData('global');
if (!sd.user_prefs) sd.user_prefs = { _schema_version: 1, _history: [] };
const prefs = sd.user_prefs;
const changes = [];
const delta   = {};
let m;

// ── Location ──────────────────────────────────────────────────────────────
if ((m = msg.match(/(?:i['\u2019]?m (?:based |located )?in|location[:\s]+|moved? to|set location (?:to )?)\s*([\w\s,]+?)(?:\s*$|[.,!?])/))) {
  const loc = m[1].trim();
  if (loc.length > 2) delta.location_canonical = loc;
}

// ── Remote ────────────────────────────────────────────────────────────────
if (/always remote|remote only|remote-only/.test(msg))           delta.remote_preference = 'remote_only';
else if (/hybrid(?:\s+ok)?|open to hybrid/.test(msg))           delta.remote_preference = 'hybrid_ok';
else if (/in.?office only|no remote/.test(msg))                  delta.remote_preference = 'in_office_only';

// ── Visa ──────────────────────────────────────────────────────────────────
const visaSigs = [];
if (/cap.?exempt/.test(msg))            visaSigs.push('cap-exempt');
if (/h1b|h-1b/.test(msg))               visaSigs.push('h1b');
if (/sponsorship|sponsor/.test(msg))    visaSigs.push('sponsorship');
if (visaSigs.length) delta.visa_signals = visaSigs;

// ── Salary ────────────────────────────────────────────────────────────────
if ((m = msg.match(/(?:min(?:imum)? salary|at least|salary[:\s]+|above|over)\s*\$?([\d]+(?:k|,\d{3})?)/))) {
  delta.salary_signals = ['$' + m[1]];
}

// ── Seniority ────────────────────────────────────────────────────────────
if (/\bsenior\b|\bstaff\b|\bprincipal\b/.test(msg))        delta.seniority = 'senior';
else if (/mid.?level|mid level/.test(msg))                       delta.seniority = 'mid';
else if (/junior|entry.?level|new grad/.test(msg))               delta.seniority = 'junior';

// ── Verbose ───────────────────────────────────────────────────────────────
if (/verbose on/.test(msg))  delta.verbose = true;
if (/verbose off/.test(msg)) delta.verbose = false;

// ── Max YOE ───────────────────────────────────────────────────────────────
if ((m = msg.match(/(?:max(?:imum)?|less than|under|at most)\s*(\d+)\s*(?:years?|yrs?|yoe)/))) {
  delta.max_yoe = parseInt(m[1], 10);
}

// ── Freshness ────────────────────────────────────────────────────────────
if (/past day|last 24|qdr:d|daily/.test(msg))                    delta.freshness = 'qdr:d';
else if (/past week|last week|qdr:w/.test(msg))                  delta.freshness = 'qdr:w';
else if (/past month|last month|qdr:m/.test(msg))                delta.freshness = 'qdr:m';

// ── Schedule times (rounded to 3-hour boundary) ──────────────────────────
const schedCtx   = /schedul[a-z]*|digest|every (?:morning|day|weekday|evening|afternoon)|send (?:me )?(?:jobs|searches)|run at|fire at|jobs at/i;
const disableCtx = /stop|disable|pause|turn off|no more|halt|cancel/i;

if (schedCtx.test(msg)) {
  if (disableCtx.test(msg)) {
    delta.schedule_times = [];
  } else {
    const timeRe = /\b(\d{1,2})(?::(\d{2}))?\s*(am|pm|a\.m\.|p\.m\.)?\b/gi;
    const found  = new Set();
    let tm;
    while ((tm = timeRe.exec(msg)) !== null) {
      let hr = parseInt(tm[1], 10);
      const mn = tm[2] ? parseInt(tm[2], 10) : 0;
      const mer = tm[3] ? tm[3].toLowerCase().replace(/\./g,'') : null;
      if (hr > 23) continue;
      if (!mer) {
        if (hr >= 1 && hr <= 7) hr += 12;
        else if (hr === 0) continue;
      } else {
        if (mer === 'pm' && hr < 12) hr += 12;
        if (mer === 'am' && hr === 12) hr = 0;
      }
      // Round to nearest 3-hour boundary (00, 03, 06, 09, 12, 15, 18, 21)
      const total   = hr * 60 + mn;
      const rounded = Math.round(total / 180) * 180;
      const rh = String(Math.floor(rounded / 60) % 24).padStart(2, '0');
      found.add(`${rh}:00`);
    }
    if (found.size > 0) delta.schedule_times = [...found].sort();
  }
}

// ── Schedule query (what the recurring digest searches for) ─────────────
if ((m = msg.match(/(?:scheduled?[\s_]?query|digest query)\s*[:\s]+(.+)$/i))) {
  const q = m[1].trim().replace(/[.!]+$/, '');
  if (q.length > 3) delta.schedule_query = q;
} else if ((m = msg.match(/for (?:my |the )?(?:scheduled?|recurring) (?:jobs?|search|digest)s?,?\s*(?:search for|find|search)\s+(.+)$/i))) {
  const q = m[1].trim().replace(/[.!]+$/, '');
  if (q.length > 3) delta.schedule_query = q;
}

// ── Resume sections (which sections to include in generated resumes) ────
// Canonical ids: summary, experience, internships, education, projects, skills,
// certifications, achievements, activities. Requires an explicit colon (like
// schedule_query:) to avoid false-positive matches on ordinary sentences.
const CANONICAL_SECTIONS = ['summary', 'experience', 'internships', 'education', 'projects', 'skills', 'certifications', 'achievements', 'activities'];
if ((m = msg.match(/\bsections\s*:\s*([a-z, ]+?)(?:[.!]|$)/i))) {
  const list = m[1].split(',').map((s) => s.trim().toLowerCase()).filter((s) => CANONICAL_SECTIONS.includes(s));
  if (list.length) delta.enabled_sections = [...new Set(list)];
}

// ── Resume section order (exact order + membership -- highest priority) ──
if ((m = msg.match(/\border\s*:\s*([a-z, ]+?)(?:[.!]|$)/i))) {
  const list = m[1].split(',').map((s) => s.trim().toLowerCase()).filter((s) => CANONICAL_SECTIONS.includes(s));
  if (list.length) delta.section_order = [...new Set(list)];
}

// ── Resume template density (compact = fewer bullets/education entries, ──
// tighter spacing; normal = default). Colon required, same convention as
// sections:/order:, to avoid false-positive matches on ordinary sentences.
if ((m = msg.match(/\btemplate\s*:\s*(compact|normal)\b/i))) {
  delta.template = m[1].toLowerCase();
}

// ── Timezone ──────────────────────────────────────────────────────────────
if ((m = msg.match(/(?:timezone|time zone|tz)\s*(?:to|=|:)?\s*([\w]+\/[\w_\/]+)/i))) {
  delta.timezone = m[1];
}

// ── Apply delta ──────────────────────────────────────────────────────────
for (const [key, val] of Object.entries(delta)) {
  if (JSON.stringify(prefs[key]) !== JSON.stringify(val)) {
    const old = prefs[key];
    prefs[key] = val;
    changes.push('• ' + key + ': ' + (old !== undefined ? JSON.stringify(old) + ' → ' : '') + JSON.stringify(val));
  }
}

if (!changes.length) {
  return [{ json: { message: "ℹ️ I didn\'t catch a clear preference there\\. Try:\n• \"I\'m in NYC\"\n• \"always remote only\"\n• \"min salary $150k\"\n• \"send me jobs at 9am and 6pm\" (rounded to 3-hour boundaries)\n• \"stop scheduled jobs\"" } }];
}

prefs._history = prefs._history || [];
prefs._history.push({ ts: new Date().toISOString(), delta });
if (prefs._history.length > 20) prefs._history = prefs._history.slice(-20);
prefs._updated_at = new Date().toISOString();

const firstKey = Object.keys(delta)[0];
return [{ json: { message: '✅ *Preferences updated:*\n' + changes.join('\n') + '\n\n_Reply \\`/prefs\\` to see all, \\`/prefs forget ' + firstKey + '\\` to remove\\._' } }];

// Handle Pref Forget
const msg   = $('Extract Input').first().json.message_text || '';
const match = msg.match(/forget\s+([a-z_]+)/i);
const key   = match?.[1]?.toLowerCase();
const sd    = $getWorkflowStaticData('global');
const prefs = sd.user_prefs || {};

if (key === 'schedule_times' && prefs[key] !== undefined) {
  // s52: deleting this key does NOT disable digests -- Schedule Gate's own
  // tri-state reads 'unset' as 'use the 09:00/18:00 defaults', so forgetting
  // it would silently RE-ENABLE them. Set to the real disabled state instead.
  prefs[key] = [];
  prefs._updated_at = new Date().toISOString();
  return [{ json: { message: '✅ Scheduled digests disabled (forgetting this preference does not restore the defaults -- say \'enable my schedule\' if you want them back).' } }];
}
if (key && prefs[key] !== undefined) {
  delete prefs[key];
  prefs._updated_at = new Date().toISOString();
  return [{ json: { message: '✅ Removed preference: *' + key + '*\n\n_Reply \\`/prefs\\` to see remaining preferences\\._' } }];
}

const available = Object.keys(prefs).filter(k => !k.startsWith('_'));
const listStr   = available.length ? available.join(', ') : '(none yet)';
return [{ json: { message: 'ℹ️ No preference named *' + (key || '?') + '* found\.\n\n_Available: ' + listStr + '_' } }];

// Toggle Verbose Mode
const msg = $('Extract Input').first().json.message_text || '';
const on  = /on|enable|yes|true/i.test(msg);
const sd  = $getWorkflowStaticData('global');
if (!sd.user_prefs) sd.user_prefs = {};
sd.user_prefs.verbose    = on;
sd.user_prefs._updated_at = new Date().toISOString();
const state  = on ? 'ON 🔔' : 'OFF 🔕';
const detail = on
  ? "I\'ll confirm what I understood before each search\\. Reply \"edit\" to refine\\."
  : "Searches will run silently\\. Send /verbose on anytime to re-enable\\.";
return [{ json: { message: `🔔 Verbose mode: *${state}*\n${detail}` } }];

// Schedule Gate
// Decides whether the current 3-hour tick fire matches a user-configured slot.
// Returns [] (silent short-circuit) if not.
//
// User prefs ($getWorkflowStaticData("global").user_prefs):
//   schedule_times: ["09:00", "18:00"]   (HH:MM 24h, 3-hour-aligned)
//                                         unset → use defaults
//                                         empty array → schedule disabled
//   timezone:       "America/New_York"   (IANA tz)
//
// Slots are rounded to the nearest 3-hour boundary (00, 03, 06, 09, 12, 15, 18, 21)
// so any user-stored time matches the tick fires correctly.
// 30-minute last-fire guard prevents accidental double-fires.

const sd = $getWorkflowStaticData("global");
const prefs = sd.user_prefs || {};

let slots;
if (prefs.schedule_times === undefined) {
  slots = ["09:00", "18:00"];
} else if (Array.isArray(prefs.schedule_times) && prefs.schedule_times.length === 0) {
  return [];
} else if (Array.isArray(prefs.schedule_times)) {
  slots = prefs.schedule_times;
} else {
  slots = ["09:00", "18:00"];
}

const tz = prefs.timezone || "America/New_York";

const fmt = new Intl.DateTimeFormat("en-US", {
  timeZone: tz, hour12: false, hour: "2-digit", minute: "2-digit"
});
const parts = Object.fromEntries(fmt.formatToParts(new Date()).map(p => [p.type, p.value]));
const nowHHMM = `${parts.hour}:${parts.minute}`;

// Round HH:MM to nearest 3-hour boundary (00, 03, 06, 09, 12, 15, 18, 21)
const round3h = (hhmm) => {
  const [h, m] = hhmm.split(":").map(Number);
  const totalMinutes = h * 60 + m;
  // 180 minutes = 3 hours
  const rounded = Math.round(totalMinutes / 180) * 180;
  const rh = String(Math.floor(rounded / 60) % 24).padStart(2, "0");
  return `${rh}:00`;
};

const nowSlot = round3h(nowHHMM);
const normalizedSlots = slots.map(round3h);
if (!normalizedSlots.includes(nowSlot)) return [];

// Last-fire guard: skip if same slot fired within last 30 minutes
sd._schedule_lastfire = sd._schedule_lastfire || {};
const lastFiredAt = sd._schedule_lastfire[nowSlot];
const nowMs = Date.now();
if (lastFiredAt && (nowMs - lastFiredAt) < 30 * 60 * 1000) return [];

sd._schedule_lastfire[nowSlot] = nowMs;
const cutoff = nowMs - 7 * 24 * 60 * 60 * 1000;
for (const k of Object.keys(sd._schedule_lastfire)) {
