  };
});
sd.last_jobs = last_jobs;
sd.last_jobs_created_at = new Date().toISOString();

return [{ json: { message: msg, telegraph_url: telegraphUrl, total_jobs: totalJobs } }];

// Build Scrape Body — produces a clean Firecrawl /v2/scrape body
// Used by Scrape Job Page (community node) with useCustomBody: true.
