}

const resumeDoc = scrub(pending.value.resume_doc);
sd.last_resume_structured = resumeDoc;

return [{ json: {
  id: 'global:resume_structured',
  scope: 'global',
  key: 'resume_structured',
  value: resumeDoc,
  chat_id: cb.chat_id,
  callback_query_id: cb.callback_query_id
} }];

// Detect Setup Sub-Intent — long paste vs short prompt request
const ctx = $('Extract Input').first().json;
const text = ctx.message_text || '';
const looksLikeResume = text.length > 800 || /^\s*\{/.test(text);
return [{ json: {
  ...ctx,
  _setup_action: looksLikeResume ? 'normalize' : 'prompt',
  resume_text: looksLikeResume ? text : ''
} }];

// Build Bubble Preview v2 — HTML-safe Telegram preview for resume_bubbles.
const upstream = $input.first().json || {};
const r = upstream.resume_doc;
const chatId = upstream.chat_id;

function arr(v) { return Array.isArray(v) ? v : []; }
function firstPrimary(a) { return arr(a).find(x => x && x.primary) || arr(a)[0] || {}; }
function clean(v) {
  const s = (v === null || v === undefined) ? '' : String(v).trim();
  if (!s || s.toLowerCase() === 'undefined' || s.toLowerCase() === 'null') return '';
  return s;
}
function esc(v) {
