}
function locToString(loc) {
  if (!loc) return '';
  if (typeof loc === 'string') return clean(loc);
  return [loc.city, loc.region, loc.country].map(clean).filter(Boolean).join(', ');
}
function flatSkills(skills) {
  const out = [];
  if (skills && typeof skills === 'object') {
    for (const vals of Object.values(skills)) if (Array.isArray(vals)) out.push(...vals);
  }
  return [...new Set(out.map(s => String(s).trim()).filter(Boolean))];
}

if (upstream._error || !r) {
  return [{
    json: {
      chat_id: chatId,
      message_text: '⚠️ <b>Resume parse failed</b>\n\n' + esc(upstream._error || 'Could not parse resume text.') + '\n\nPlease try another PDF/DOCX/TXT or paste the resume body directly.',
      reply_markup: null,
      resume_doc: r || null
    }
  }];
}

const p = r.personal || r.profile || {};
const email = firstPrimary(p.emails).address || p.email || '—';
const phone = firstPrimary(p.phones).number || p.phone || '—';
const loc = locToString(firstPrimary(p.locations)) || clean(p.location) || '—';
const expCount = arr(r.experience).length || arr(r.bubbles).filter(b => b.type === 'experience').length;
const projCount = arr(r.projects).length || arr(r.bubbles).filter(b => b.type === 'project').length;
const eduCount = arr(r.education).length || arr(r.bubbles).filter(b => b.type === 'education').length;
const bubbleCount = arr(r.bubbles).length;
const skillList = flatSkills(r.skills);
const metricCount = arr(r.bubbles).reduce((n, b) => n + arr(b.metrics).length, 0);
const confidence = r.metadata?.parse_confidence ?? upstream._meta?.parse_confidence ?? null;
const warnings = r.metadata?.parse_warnings || upstream._meta?.warnings || [];

let msg = '📄 <b>Resume Bubbles — Preview</b>\n\n';
msg += `<b>Name:</b> ${esc(p.name) || '—'}\n`;
if (clean(p.headline)) msg += `<b>Headline:</b> ${esc(clean(p.headline).slice(0, 120))}${clean(p.headline).length > 120 ? '...' : ''}\n`;
msg += `<b>Email:</b> ${esc(email)}\n`;
msg += `<b>Phone:</b> ${esc(phone)}\n`;
msg += `<b>Location:</b> ${esc(loc)}\n`;

msg += '\n<b>Detected bubbles:</b>\n';
msg += `• Experience: ${expCount}\n`;
msg += `• Projects: ${projCount}\n`;
msg += `• Education: ${eduCount}\n`;
msg += `• Total evidence bubbles: ${bubbleCount}\n`;
msg += `• Skills: ${skillList.length}\n`;
if (metricCount) msg += `• Metrics found: ${metricCount}\n`;
if (confidence !== null) msg += `• Parse confidence: ${Math.round(Number(confidence) * 100)}%\n`;

if (skillList.length) {
  msg += '\n<b>Top skills:</b>\n';
  msg += esc(skillList.slice(0, 18).join(', ') + (skillList.length > 18 ? '...' : '')) + '\n';
}

const recent = arr(r.experience)[0] || arr(r.bubbles).find(b => b.type === 'experience');
if (recent) {
  msg += '\n<b>Most recent role:</b>\n';
  msg += `${esc(clean(recent.title) || 'Role')}${clean(recent.company || recent.organization) ? ' @ ' + esc(clean(recent.company || recent.organization)) : ''}\n`;
  const dates = [clean(recent.start_date), recent.is_current ? 'current' : clean(recent.end_date)].filter(Boolean).join(' → ');
  if (dates) msg += `${esc(dates)}\n`;
}

if (warnings.length) {
  msg += '\n⚠️ <b>Review notes:</b>\n';
  msg += warnings.slice(0, 3).map(w => '• ' + esc(w)).join('\n') + '\n';
}

msg += '\n<i>No LLM was used for this setup parse. I saved sections as reusable resume bubbles so later generation can use only the relevant evidence.</i>';
msg += '\n\n<i>Tap a button below:</i>';

const reply_markup = {
  inline_keyboard: [
    [
      { text: '✅ Looks good — save it', callback_data: 'resume:apply' },
      { text: '❌ Cancel', callback_data: 'resume:cancel' }
    ],
    [
      { text: '✏️ Re-upload / paste again', callback_data: 'resume:redo' }
    ]
  ]
};

return [{
